  const stack = [];
  let current = '', num = 0;
  for (const c of str) {
    if (c >= '0' && c <= '9') num = num * 10 + Number(c);
    else if (c === '[') { stack.push([current, num]); current = ''; num = 0; }
    else if (c === ']') { const [prev, n] = stack.pop(); current = prev + current.repeat(n); }
    else current += c;
  }
  return current;
}
